<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
class Reminder extends Model {protected $fillable=['purchase_id','customer_id','stage','due_date','status','channel','handled_by','handled_at','note'];protected $casts=['due_date'=>'date','handled_at'=>'datetime'];public const STAGES=['h7'=>'H+7 — cek kepuasan','m1'=>'1 bulan — cek kepuasan + tawarkan aksesoris','m6'=>'6 bulan — upsell aksesoris/servis rutin','m12'=>'12 bulan — garansi mau habis + upgrade/tukar tambah'];public const STAGE_DAYS=['h7'=>7,'m1'=>30,'m6'=>182,'m12'=>365];public function purchase():BelongsTo{return $this->belongsTo(Purchase::class);}public function customer():BelongsTo{return $this->belongsTo(Customer::class);}public function handler():BelongsTo{return $this->belongsTo(User::class,'handled_by');}public function stageLabel():string{return self::STAGES[$this->stage]??$this->stage;}}
